column8:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "name": "vod_search_all",
  "description": "影视媒资组合式搜索与起播工具(vod_search_all)。当用户表达搜索、查找、推荐或播放影视内容的意图时触发。请求必须通过action指定操作类型：search表示搜索，play表示起播。支持24个精确匹配维度(title/actor/director/area/category/channel等)、2个状态维度(is_fee：0免费、1付费；is_over：0连载中、1已完结)、3个范围维度(age_range年龄范围、release_time发布时间范围，格式yyyyMMdd；rate评分范围0～10)以及3个起播控制维度(series部数或季数、video_index集数或期数、voiceStartPos起播位置，单位为秒)。同一精确匹配维度包含多个值时，使用values数组传递，并通过operator指定逻辑关系：or表示任一值匹配，and表示所有值均需匹配，默认为or。不同维度之间通过BoolNode使用and(与)、or(或)、not(非)组合，支持任意嵌套。",
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "search",
        "play"
      ],
      "description": "操作类型：search 表示普通搜索，play 表示起播"
    },
    "retext": {
      "type": "string",
      "minLength": 1,
      "pattern": ".*\\S.*",
      "description": "用户输入的原始文本。"
    },
    "query": {
      "$ref": "#/definitions/QueryNode",
      "description": "搜索查询的根节点。可以是单个叶子节点，也可以是由 AND/OR/NOT 组成的复合节点。"
    },
    "sort": {
      "type": "object",
      "description": "排序规则，可选 rate(评分)、hot(热度)、new(发布时间)、play(播放量) 中的一种或多种组合。",
      "properties": {
        "rate": {
          "type": "object",
          "properties": {
            "order": {
              "type": "string",
              "enum": [
                "asc",
                "desc"
              ]
            }
          },
          "required": [
            "order"
          ]
        },
        "hot": {
          "type": "object",
          "properties": {
            "order": {
              "type": "string",
              "enum": [
                "asc",
                "desc"
              ]
            }
          },
          "required": [
            "order"
          ]
        },
        "new": {
          "type": "object",
          "properties": {
            "order": {
              "type": "string",
              "enum": [
                "asc",
                "desc"
              ]
            }
          },
          "required": [
            "order"
          ]
        },
        "play": {
          "type": "object",
          "properties": {
            "order": {
              "type": "string",
              "enum": [
                "asc",
                "desc"
              ]
            }
          },
          "required": [
            "order"
          ]
        }
      },
      "additionalProperties": false,
      "minProperties": 1
    }
  },
  "required": [
    "action",
    "retext",
    "query"
  ],
  "additionalProperties": false,
  "definitions": {
    "QueryNode": {
      "description": "查询节点，支持三种形态：1) 布尔复合节点(AND/OR/NOT)；2) 叶子条件节点(单个字段的匹配条件)。",
      "oneOf": [
        {
          "$ref": "#/definitions/BoolNode"
        },
        {
          "$ref": "#/definitions/LeafNode"
        }
      ]
    },
    "BoolNode": {
      "description": "布尔逻辑组合节点，支持 AND(与)、OR(或)、NOT(非) 三种组合方式。可嵌套组合。",
      "type": "object",
      "oneOf": [
        {
          "properties": {
            "and": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/QueryNode"
              },
              "minItems": 1,
              "description": "AND逻辑：所有子节点条件必须同时满足。"
            }
          },
          "required": [
            "and"
          ],
          "additionalProperties": false
        },
        {
          "properties": {
            "or": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/QueryNode"
              },
              "minItems": 1,
              "description": "OR逻辑：子节点条件中至少满足一个。"
            }
          },
          "required": [
            "or"
          ],
          "additionalProperties": false
        },
        {
          "properties": {
            "not": {
              "$ref": "#/definitions/QueryNode",
              "description": "NOT逻辑：对子节点条件取反。"
            }
          },
          "required": [
            "not"
          ],
          "additionalProperties": false
        }
      ]
    },
    "LeafNode": {
      "description": "叶子条件节点，描述对某一搜索维度的具体匹配条件。field 指定维度，value 指定匹配值。",
      "type": "object",
      "oneOf": [
        {
          "$ref": "#/definitions/ExactFieldCondition"
        },
        {
          "$ref": "#/definitions/StatusFieldCondition"
        },
        {
          "$ref": "#/definitions/RangeFieldCondition"
        },
        {
          "$ref": "#/definitions/PlaybackControlFieldCondition"
        }
      ]
    },
    "ExactFieldCondition": {
      "description": "精确匹配条件。value 为单值精确匹配；values 为多值数组时，通过 operator 字段控制维度内的逻辑关系：\"or\" 表示任一值匹配即命中(默认)，\"and\" 表示所有值均需匹配。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "搜索维度字段名",
          "oneOf": [
            {
              "const": "title",
              "description": "媒资标题。如：电影名(战狼、流浪地球)、电视剧名(甄嬛传)、综艺名(天天向上、快乐大本营)、动漫名(龙猫、棋魂)、动画片名(汪汪队、小猪佩奇)、小品名(真假皇后)、相声名、评书名(追画、扯画轴)、戏曲名(满江红)、歌曲名(小苹果、月亮之上)、游戏名(王者荣耀、斗罗大陆)、晚会名(春节晚会)、新闻节目(四川新闻)、网络热梗(绝绝子)、短视频标题、吃播、美妆视频、玩具名(陀螺)、萌宠(猫、狗)、魔术、杂技、快板、漫画名、小说名等"
            },
            {
              "const": "actor",
              "description": "演员。如：影视演员(刘德华、邓超)、小品演员(岳云鹏、小沈阳)、相声演员(张鹤伦)、戏曲演员(张琳)、脱口秀演员、快板演员(杨波)、评书演员、企业家(马云、雷军)、老师(郑多燕)等"
            },
            {
              "const": "director",
              "description": "导演。如：影视导演(张艺谋、冯小刚)、编剧(刘格林)、动画导演(宫崎骏)"
            },
            {
              "const": "dubbing",
              "description": "配音演员"
            },
            {
              "const": "entertainer",
              "description": "参与人员，艺人表演者包含歌手"
            },
            {
              "const": "prize",
              "description": "影视奖项"
            },
            {
              "const": "language",
              "description": "语言。如：中文、英语、日语；版本词如韩版、美版"
            },
            {
              "const": "hostess",
              "description": "主持人。如：节目主持人(何炅、谢娜)、新闻主持人(杨澜)"
            },
            {
              "const": "role",
              "description": "角色。如：动漫角色(路飞)、神话人物(雅典娜、潘多拉)、影视剧角色(苏明玉、孙悟空)、漫画角色等"
            },
            {
              "const": "creation_source",
              "description": "剧本来源。如：小说改编、原创等"
            },
            {
              "const": "sound",
              "description": "音效。如：杜比、杜比音效"
            },
            {
              "const": "tag",
              "description": "标签。如：儿歌(童谣)、动漫、戏曲(歌剧、话剧)、演唱会(音乐会)、动画片、记录片、城市(哥伦布、桂林)、影视类型/主题、动漫主题(暗黑、格斗)、游戏、歌曲、宠物种类(变色龙、龙猫)、杂技(顶碗、转碟)、旅游、脱口秀、歌剧(喜剧、儿童剧)、颁奖晚会、诗歌(唐诗、宋词)、历史事件(楚汉之争、昭君出塞)、小说名、小品相声主题、电影榜单、影视片段、版本词(番外、真人版)、少儿分类等"
            },
            {
              "const": "sub_prize",
              "description": "子奖项。如：最佳男配角、最佳女主角"
            },
            {
              "const": "target",
              "description": "受众。如：适用人群、婴儿、儿童、少儿"
            },
            {
              "const": "vender_name",
              "description": "供应商名称。如：视频网站(豆瓣、芒果TV)、提供商"
            },
            {
              "const": "company",
              "description": "出品公司。如：影视出品公司(时光传媒)"
            },
            {
              "const": "writer",
              "description": "作者。如：小说作者(唐家三少)、作家(三毛、曾国藩)、漫画作者"
            },
            {
              "const": "definition",
              "description": "清晰度，目前仅支持3D和4K。枚举值：is_3d(3D)、is_4k(4K)"
            },
            {
              "const": "area",
              "description": "地区。如：国内(内地)、中国区域(中华、香港)、国外区域(中东、欧亚)、外国国家(卢森堡、苏格兰)"
            },
            {
              "const": "category",
              "description": "影视分类。如：电影、电视剧、纪录片、综艺、戏曲、新闻、资讯、片花、短视频、广告、正片"
            },
            {
              "const": "channel",
              "description": "频道"
            },
            {
              "const": "comedy_brand",
              "description": "喜剧厂牌"
            },
            {
              "const": "gender",
              "description": "性别。男性、女性"
            },
            {
              "const": "technology",
              "description": "拍摄技术。如：3D、全景拍摄"
            }
          ]
        },
        "value": {
          "type": "string",
          "description": "单值精确匹配"
        },
        "values": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "minItems": 1,
          "description": "多值匹配，逻辑关系由 operator 字段决定"
        },
        "operator": {
          "type": "string",
          "enum": [
            "and",
            "or"
          ],
          "default": "or",
          "description": "维度内多值逻辑关系。\"or\" 表示任一值匹配即命中(默认)，\"and\" 表示所有值均需匹配。仅在使用 values 时生效。"
        }
      },
      "required": [
        "field"
      ],
      "oneOf": [
        {
          "required": [
            "value"
          ]
        },
        {
          "required": [
            "values"
          ]
        }
      ],
      "additionalProperties": false
    },
    "StatusFieldCondition": {
      "description": "状态标识条件。用于枚举状态字段，值为 0 或 1 的整数。is_fee: 0=免费, 1=付费；is_over: 0=连载中, 1=已完结。不传表示不涉及该条件。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "状态字段名",
          "oneOf": [
            {
              "const": "is_fee",
              "description": "免付费标识。0=免费，1=付费"
            },
            {
              "const": "is_over",
              "description": "视频状态。0=连载中，1=已完结"
            }
          ]
        },
        "value": {
          "type": "integer",
          "enum": [
            0,
            1
          ],
          "description": "状态值，0 或 1。"
        }
      },
      "required": [
        "field",
        "value"
      ],
      "additionalProperties": false
    },
    "RangeFieldCondition": {
      "description": "范围匹配条件。支持 age_range(年龄范围) 和 release_time(发布时间范围) rate（评分）三个范围字段。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "enum": [
            "age_range",
            "release_time",
            "rate"
          ],
          "description": "范围搜索维度字段名"
        },
        "from": {
          "description": "范围起始值(含)。age_range 为整数，release_time 为 yyyyMMdd 格式字符串,rate为0 到 10 的数字，支持小数。"
        },
        "to": {
          "description": "范围结束值(含)。age_range 为整数，release_time 为 yyyyMMdd 格式字符串,rate为0 到 10 的数字，支持小数。"
        }
      },
      "required": [
        "field",
        "from",
        "to"
      ],
      "additionalProperties": false,
      "allOf": [
        {
          "if": {
            "properties": {
              "field": {
                "const": "age_range"
              }
            }
          },
          "then": {
            "properties": {
              "from": {
                "type": "integer",
                "minimum": 0,
                "description": "年龄下限(含)"
              },
              "to": {
                "type": "integer",
                "minimum": 0,
                "description": "年龄上限(含)"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "field": {
                "const": "release_time"
              }
            }
          },
          "then": {
            "properties": {
              "from": {
                "type": "string",
                "pattern": "^[0-9]{8}$",
                "description": "发布日期下限，格式 yyyyMMdd，如 20200101"
              },
              "to": {
                "type": "string",
                "pattern": "^[0-9]{8}$",
                "description": "发布日期上限，格式 yyyyMMdd，如 20231231"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "field": {
                "const": "rate"
              }
            }
          },
          "then": {
            "properties": {
              "from": {
                "type": "number",
                "minimum": 0,
                "maximum": 10
              },
              "to": {
                "type": "number",
                "minimum": 0,
                "maximum": 10
              }
            }
          }
        }
      ]
    },
    "PlaybackControlFieldCondition": {
      "description": "起播控制字段。使用 field/value 形式，与 title 等检索槽位保持一致；可参与 and、or、not。",
      "oneOf": [
        {
          "type": "object",
          "properties": {
            "field": {
              "const": "series",
              "description": "剧集部数或季数。"
            },
            "value": {
              "type": "integer",
              "minimum": 1,
              "description": "第几部或第几季的序号，从 1 开始。例如第二季传 2。"
            }
          },
          "required": [
            "field",
            "value"
          ],
          "additionalProperties": false
        },
        {
          "type": "object",
          "properties": {
            "field": {
              "const": "video_index",
              "description": "剧集集数或综艺期数。"
            },
            "value": {
              "type": "integer",
              "minimum": 1,
              "description": "第几集或第几期的序号，从 1 开始。例如第三集传 3。"
            }
          },
          "required": [
            "field",
            "value"
          ],
          "additionalProperties": false
        },
        {
          "type": "object",
          "properties": {
            "field": {
              "const": "voiceStartPos",
              "description": "起播时间位置。"
            },
            "value": {
              "type": "integer",
              "minimum": 0,
              "description": "起播位置，单位为秒。例如第 10 分钟传 600，3 分 09 秒传 189。"
            }
          },
          "required": [
            "field",
            "value"
          ],
          "additionalProperties": false
        }
      ]
    }
  }
}

column9:
{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "智能体（影视、少儿）": {
            "type": "object",
            "properties": {
                "code": {
                    "type": "string",
                    "description": "接口返回状态码"
                },
                "data": {
                    "type": "object",
                    "properties": {
                        "ttscontent": {
                            "type": "string",
                            "description": "提示语\n对于影视智能体解析到问答意图的场景，统一返回默认值\"这个问题太深奥了，小聚还在学习呢\"\n\n对于少儿智能体解析到问答意图的场景，统一返回默认值\"这个问题太深奥了，小聚还在学习呢\""
                        },
                        "llmSemantic": {
                            "type": "object",
                            "properties": {
                                "query": {
                                    "type": "string"
                                },
                                "vectorQuery": {
                                    "type": "string",
                                    "description": "【新增】向量检索Query"
                                },
                                "domain": {
                                    "type": "string",
                                    "description": "固定值\n影视=影视领域（VIDEO_TOPIC）\n少儿=少儿领域（EDUC_TOPIC）"
                                },
                                "intent": {
                                    "type": "string",
                                    "description": "意图信息，按业务划分\n陪伴机器人新增vod_companion_robot_unsupported不支持意图"
                                },
                                "isNewVersion": {
                                    "type": "boolean",
                                    "description": "【新增】用于区分是否新版本，不传参默认false \n\n少儿智能体不需要传此值"
                                },
                                "content": {
                                    "type": "string",
                                    "description": "\"content\": \"{\\\"queryRetrievalIntent\\\":\\\"Multi_retrieval_intent\\\"}\"影视模糊意图下二次请求需要的必要参数，需终端二次流式请求时透传。 影视2.1新增wordList"
                                },
                                "largeModelSlotData": {
                                    "type": "object",
                                    "properties": {

                                    },
                                    "description": "大模型提槽信息(除模糊检索、个性化模糊检索和知识问答意图外其他意图可不传该值)"
                                },
                                "originalQuery": {
                                    "type": "string",
                                    "description": "原始query (除模糊检索、个性化模糊检索和知识问答意图外其他意图可不传该值)"
                                },
                                "rewriteQuery": {
                                    "type": "string",
                                    "description": "模型改写后的query (除模糊检索、个性化模糊检索和知识问答意图外其他意图可不传该值)"
                                }
                            },
                            "description": "意图信息",
                            "required": [
                                "domain",
                                "intent"
                            ]
                        },
                        "data": {
                            "type": "object",
                            "properties": {

                            },
                            "description": "媒资信息：按业务区分示例：\n影视=http://10.18.229.83:3000/project/1723/interface/api/185520\n少儿=http://10.18.229.83:3000/project/1723/interface/api/187527"
                        },
                        "ttsPolishParam": {
                            "type": "object",
                            "properties": {

                            },
                            "description": "精确搜索tts润色参数，精确搜索时必传，详见：http://10.18.229.83:3000/project/1753/interface/api/185418\n\n少儿精确搜索tts润色\nhttp://10.18.229.83:3000/project/1753/interface/api/188767"
                        },
                        "iotinfocheck": {
                            "type": "string",
                            "description": "(不确定含义，暂时保留)\n用于下发给终端标识，终端检测聚好看的推荐接口"
                        },
                        "multispeech": {
                            "type": "string",
                            "description": "（保留）多轮语音参数"
                        },
                        "ttsReplace": {
                            "type": "string",
                            "description": "（保留）\n是否需要RTG替换"
                        },
                        "sort": {
                            "type": "string",
                            "description": "（保留）\n分类，相同的UI下发sort相同\n对于影视智能体解析到问答意图的场景，统一返回默认值\"chatting\"\n"
                        },
                        "priority": {
                            "type": "string",
                            "description": "（保留）\n用于终端，是否优先级处理界面词"
                        },
                        "subsort": {
                            "type": "string",
                            "description": "（保留）子分类\n对于影视智能体解析到问答意图的场景，统一返回默认值\"chatting\"\n\n对于少儿 智能体解析到问答意图的场景，统一返回默认值\"chatting\""
                        },
                        "screenoper": {
                            "type": "string",
                            "description": "（保留）开关屏的参数，1：终端执行开屏，0：终端执行关屏，3：终端需要特殊逻辑处理"
                        },
                        "logId": {
                            "type": "string",
                            "description": "(确认含义，是否保留)请求参数中的logId。若logId为空，内部自动生成"
                        },
                        "fullduplex": {
                            "type": "string",
                            "description": "全双工参数，1：终端执行全双工交互，默认是0"
                        },
                        "extradata": {
                            "type": "object",
                            "properties": {
                                "video": {
                                    "type": "object",
                                    "properties": {
                                        "videorecommand": {
                                            "type": "array",
                                            "items": {
                                                "type": "object",
                                                "properties": {
                                                    "videonum": {
                                                        "type": "number",
                                                        "description": "资源编号"
                                                    },
                                                    "isrecommand": {
                                                        "type": "boolean",
                                                        "description": "资源编号"
                                                    }
                                                },
                                                "required": [
                                                    "videonum",
                                                    "isrecommand"
                                                ]
                                            }
                                        }
                                    },
                                    "description": "视频服务结果"
                                }
                            },
                            "description": "用于存放与业务无关参数；-----魔方屏增加"
                        },
                        "debugLog": {
                            "type": "object",
                            "properties": {

                            },
                            "description": "debug调试日志，不返回给终端；map结构，根据业务自行组装"
                        },
                        "memoryData": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "sort": {
                                        "type": "string",
                                        "description": "数据类别 少儿、影视固定为 hisapp"
                                    },
                                    "subsort": {
                                        "type": "string",
                                        "description": "数据子类 少儿、影视固定为 video"
                                    },
                                    "recognitionType": {
                                        "type": "string",
                                        "description": "识别类型，小聚识图用，其他来源传空字符串"
                                    },
                                    "text": {
                                        "type": "string",
                                        "description": "业务数据播报tts"
                                    },
                                    "serviceId": {
                                        "type": "string",
                                        "description": "服务Id 少儿固定值为 CHILD_AGENT_SERVICE\n影视固定值为 VIDEO_AGENT_SERVICE"
                                    },
                                    "data": {
                                        "type": "array",
                                        "items": {
                                            "type": "object",
                                            "properties": {
                                                "actor": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "string",
                                                        "description": ""
                                                    },
                                                    "description": "演员"
                                                },
                                                "childCategory": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "string",
                                                        "description": ""
                                                    },
                                                    "description": "子类"
                                                },
                                                "mediaTitle": {
                                                    "type": "string",
                                                    "description": "媒资名称"
                                                },
                                                "doubanRate": {
                                                    "type": "number",
                                                    "description": "豆瓣评分"
                                                },
                                                "director": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "string"
                                                    },
                                                    "description": "导演"
                                                },
                                                "guest": {
                                                    "type": "string"
                                                },
                                                "isClip": {
                                                    "type": "boolean",
                                                    "description": "是否片花"
                                                },
                                                "mediaId": {
                                                    "type": "integer",
                                                    "description": "format: int32",
                                                    "format": "int32"
                                                },
                                                "category": {
                                                    "type": "string",
                                                    "description": "种类 取categoryNameMark"
                                                },
                                                "pubdate": {
                                                    "type": "string",
                                                    "description": "发布日期"
                                                }
                                            },
                                            "required": [
                                                "actor",
                                                "childCategory",
                                                "mediaTitle",
                                                "doubanRate",
                                                "director",
                                                "category",
                                                "mediaId",
                                                "isClip",
                                                "guest",
                                                "pubdate"
                                            ]
                                        }
                                    }
                                },
                                "required": [
                                    "sort",
                                    "data",
                                    "serviceId",
                                    "text",
                                    "recognitionType",
                                    "subsort"
                                ]
                            },
                            "description": "记忆存储字段 影视不返回"
                        },
                        "memoryContent": {
                            "type": "string",
                            "description": "记忆信息存储，JSON格式字符串，其中memoryQuery存储本轮query：\n示例结构：\"memoryContent\": \"{\\\"memoryQuery\\\":\\\"query=(release_year:[20250522 TO 20260522])AND((category:\\\\\\\"电影\\\\\\\"))&sort=play,play desc,desc&appTypeSelected=1\\\"}\",\n"
                        }
                    },
                    "description": "返回数据",
                    "required": [
                        "llmSemantic",
                        "memoryData"
                    ]
                },
                "message": {
                    "type": "string",
                    "description": "接口返回状态描述"
                }
            },
            "description": "影视：bizType=vod\n少儿：bizType=educ"
        }
    },
    "required": [
        "code",
        "message",
        "data"
    ]
}

column8:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "name": "vod_search",
  "description": "影视媒资组合式搜索与起播工具(vod_search)。当用户表达搜索、查找、推荐或播放影视内容的意图时触发。请求必须通过action指定操作类型：search表示搜索，play表示起播。支持10个精确匹配维度(title/actor/director/category等)、2个状态维度(is_fee：0免费、1付费；is_over：0连载中、1已完结)、3个范围维度(age_range年龄范围、release_time发布时间范围，格式yyyyMMdd；rate评分范围0～10)以及3个起播控制维度(series部数或季数、video_index集数或期数、voiceStartPos起播位置，单位为秒)。同一精确匹配维度包含多个值时，使用values数组传递，并通过operator指定逻辑关系：or表示任一值匹配，and表示所有值均需匹配，默认为or。不同维度之间通过BoolNode使用and(与)、or(或)、not(非)组合，支持任意嵌套。",
  "type": "object",
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "search",
        "play"
      ],
      "description": "操作类型：search 表示普通搜索，play 表示起播"
    },
    "retext": {
      "type": "string",
      "minLength": 1,
      "pattern": ".*\\S.*",
      "description": "用户输入的原始文本。"
    },
    "query": {
      "$ref": "#/definitions/QueryNode",
      "description": "搜索查询的根节点。可以是单个叶子节点，也可以是由 AND/OR/NOT 组成的复合节点。"
    },
    "sort": {
      "type": "object",
      "description": "排序规则，可选 rate(评分)、hot(热度)、new(发布时间)、play(播放量) 中的一种或多种组合。",
      "properties": {
        "rate": {
          "type": "object",
          "properties": {
            "order": {
              "type": "string",
              "enum": [
                "asc",
                "desc"
              ]
            }
          },
          "required": [
            "order"
          ]
        },
        "hot": {
          "type": "object",
          "properties": {
            "order": {
              "type": "string",
              "enum": [
                "asc",
                "desc"
              ]
            }
          },
          "required": [
            "order"
          ]
        },
        "new": {
          "type": "object",
          "properties": {
            "order": {
              "type": "string",
              "enum": [
                "asc",
                "desc"
              ]
            }
          },
          "required": [
            "order"
          ]
        },
        "play": {
          "type": "object",
          "properties": {
            "order": {
              "type": "string",
              "enum": [
                "asc",
                "desc"
              ]
            }
          },
          "required": [
            "order"
          ]
        }
      },
      "additionalProperties": false,
      "minProperties": 1
    }
  },
  "required": [
    "action",
    "retext",
    "query"
  ],
  "additionalProperties": false,
  "definitions": {
    "QueryNode": {
      "description": "查询节点，支持三种形态：1) 布尔复合节点(AND/OR/NOT)；2) 叶子条件节点(单个字段的匹配条件)。",
      "oneOf": [
        {
          "$ref": "#/definitions/BoolNode"
        },
        {
          "$ref": "#/definitions/LeafNode"
        }
      ]
    },
    "BoolNode": {
      "description": "布尔逻辑组合节点，支持 AND(与)、OR(或)、NOT(非) 三种组合方式。可嵌套组合。",
      "type": "object",
      "oneOf": [
        {
          "properties": {
            "and": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/QueryNode"
              },
              "minItems": 1,
              "description": "AND逻辑：所有子节点条件必须同时满足。"
            }
          },
          "required": [
            "and"
          ],
          "additionalProperties": false
        },
        {
          "properties": {
            "or": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/QueryNode"
              },
              "minItems": 1,
              "description": "OR逻辑：子节点条件中至少满足一个。"
            }
          },
          "required": [
            "or"
          ],
          "additionalProperties": false
        },
        {
          "properties": {
            "not": {
              "$ref": "#/definitions/QueryNode",
              "description": "NOT逻辑：对子节点条件取反。"
            }
          },
          "required": [
            "not"
          ],
          "additionalProperties": false
        }
      ]
    },
    "LeafNode": {
      "description": "叶子条件节点，描述对某一搜索维度的具体匹配条件。field 指定维度，value 指定匹配值。",
      "type": "object",
      "oneOf": [
        {
          "$ref": "#/definitions/ExactFieldCondition"
        },
        {
          "$ref": "#/definitions/StatusFieldCondition"
        },
        {
          "$ref": "#/definitions/RangeFieldCondition"
        },
        {
          "$ref": "#/definitions/PlaybackControlFieldCondition"
        }
      ]
    },
    "ExactFieldCondition": {
      "description": "精确匹配条件。value 为单值精确匹配；values 为多值数组时，通过 operator 字段控制维度内的逻辑关系：\"or\" 表示任一值匹配即命中(默认)，\"and\" 表示所有值均需匹配。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "搜索维度字段名",
          "oneOf": [
            {
              "const": "title",
              "description": "媒资标题。如：电影名(战狼、流浪地球)、电视剧名(甄嬛传)、综艺名(天天向上、快乐大本营)、动漫名(龙猫、棋魂)、动画片名(汪汪队、小猪佩奇)、小品名(真假皇后)、相声名、评书名(追画、扯画轴)、戏曲名(满江红)、歌曲名(小苹果、月亮之上)、游戏名(王者荣耀、斗罗大陆)、晚会名(春节晚会)、新闻节目(四川新闻)、网络热梗(绝绝子)、短视频标题、吃播、美妆视频、玩具名(陀螺)、萌宠(猫、狗)、魔术、杂技、快板、漫画名、小说名等"
            },
            {
              "const": "actor",
              "description": "演员。如：影视演员(刘德华、邓超)、小品演员(岳云鹏、小沈阳)、相声演员(张鹤伦)、戏曲演员(张琳)、脱口秀演员、快板演员(杨波)、评书演员、企业家(马云、雷军)、老师(郑多燕)等"
            },
            {
              "const": "director",
              "description": "导演。如：影视导演(张艺谋、冯小刚)、编剧(刘格林)、动画导演(宫崎骏)"
            },
            {
              "const": "entertainer",
              "description": "参与人员，艺人表演者包含歌手"
            },
            {
              "const": "prize",
              "description": "影视奖项"
            },
            {
              "const": "role",
              "description": "角色。如：动漫角色(路飞)、神话人物(雅典娜、潘多拉)、影视剧角色(苏明玉、孙悟空)、漫画角色等"
            },
            {
              "const": "tag",
              "description": "标签。如：儿歌(童谣)、动漫、戏曲(歌剧、话剧)、演唱会(音乐会)、动画片、记录片、城市(哥伦布、桂林)、影视类型/主题、动漫主题(暗黑、格斗)、游戏、歌曲、宠物种类(变色龙、龙猫)、杂技(顶碗、转碟)、旅游、脱口秀、歌剧(喜剧、儿童剧)、颁奖晚会、诗歌(唐诗、宋词)、历史事件(楚汉之争、昭君出塞)、小说名、小品相声主题、电影榜单、影视片段、版本词(番外、真人版)、少儿分类等"
            },
            {
              "const": "target",
              "description": "受众。如：适用人群、婴儿、儿童、少儿"
            },
            {
              "const": "definition",
              "description": "清晰度，目前仅支持3D和4K。枚举值：is_3d(3D)、is_4k(4K)"
            },
            {
              "const": "category",
              "description": "影视分类。如：电影、电视剧、纪录片、综艺、戏曲、新闻、资讯、片花、短视频、广告、正片"
            }
          ]
        },
        "value": {
          "type": "string",
          "description": "单值精确匹配"
        },
        "values": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "minItems": 1,
          "description": "多值匹配，逻辑关系由 operator 字段决定"
        },
        "operator": {
          "type": "string",
          "enum": [
            "and",
            "or"
          ],
          "default": "or",
          "description": "维度内多值逻辑关系。\"or\" 表示任一值匹配即命中(默认)，\"and\" 表示所有值均需匹配。仅在使用 values 时生效。"
        }
      },
      "required": [
        "field"
      ],
      "oneOf": [
        {
          "required": [
            "value"
          ]
        },
        {
          "required": [
            "values"
          ]
        }
      ],
      "additionalProperties": false
    },
    "StatusFieldCondition": {
      "description": "状态标识条件。用于枚举状态字段，值为 0 或 1 的整数。is_fee: 0=免费, 1=付费；is_over: 0=连载中, 1=已完结。不传表示不涉及该条件。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "状态字段名",
          "oneOf": [
            {
              "const": "is_fee",
              "description": "免付费标识。0=免费，1=付费"
            },
            {
              "const": "is_over",
              "description": "视频状态。0=连载中，1=已完结"
            }
          ]
        },
        "value": {
          "type": "integer",
          "enum": [
            0,
            1
          ],
          "description": "状态值，0 或 1。"
        }
      },
      "required": [
        "field",
        "value"
      ],
      "additionalProperties": false
    },
    "RangeFieldCondition": {
      "description": "范围匹配条件。支持 age_range(年龄范围) 和 release_time(发布时间范围) rate（评分）三个范围字段。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "enum": [
            "age_range",
            "release_time",
            "rate"
          ],
          "description": "范围搜索维度字段名"
        },
        "from": {
          "description": "范围起始值(含)。age_range 为整数，release_time 为 yyyyMMdd 格式字符串,rate为0 到 10 的数字，支持小数。"
        },
        "to": {
          "description": "范围结束值(含)。age_range 为整数，release_time 为 yyyyMMdd 格式字符串,rate为0 到 10 的数字，支持小数。"
        }
      },
      "required": [
        "field",
        "from",
        "to"
      ],
      "additionalProperties": false,
      "allOf": [
        {
          "if": {
            "properties": {
              "field": {
                "const": "age_range"
              }
            }
          },
          "then": {
            "properties": {
              "from": {
                "type": "integer",
                "minimum": 0,
                "description": "年龄下限(含)"
              },
              "to": {
                "type": "integer",
                "minimum": 0,
                "description": "年龄上限(含)"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "field": {
                "const": "release_time"
              }
            }
          },
          "then": {
            "properties": {
              "from": {
                "type": "string",
                "pattern": "^[0-9]{8}$",
                "description": "发布日期下限，格式 yyyyMMdd，如 20200101"
              },
              "to": {
                "type": "string",
                "pattern": "^[0-9]{8}$",
                "description": "发布日期上限，格式 yyyyMMdd，如 20231231"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "field": {
                "const": "rate"
              }
            }
          },
          "then": {
            "properties": {
              "from": {
                "type": "number",
                "minimum": 0,
                "maximum": 10
              },
              "to": {
                "type": "number",
                "minimum": 0,
                "maximum": 10
              }
            }
          }
        }
      ]
    },
    "PlaybackControlFieldCondition": {
      "description": "起播控制字段。使用 field/value 形式，与 title 等检索槽位保持一致；可参与 and、or、not。",
      "oneOf": [
        {
          "type": "object",
          "properties": {
            "field": {
              "const": "series",
              "description": "剧集部数或季数。"
            },
            "value": {
              "type": "integer",
              "minimum": 1,
              "description": "第几部或第几季的序号，从 1 开始。例如第二季传 2。"
            }
          },
          "required": [
            "field",
            "value"
          ],
          "additionalProperties": false
        },
        {
          "type": "object",
          "properties": {
            "field": {
              "const": "video_index",
              "description": "剧集集数或综艺期数。"
            },
            "value": {
              "type": "integer",
              "minimum": 1,
              "description": "第几集或第几期的序号，从 1 开始。例如第三集传 3。"
            }
          },
          "required": [
            "field",
            "value"
          ],
          "additionalProperties": false
        },
        {
          "type": "object",
          "properties": {
            "field": {
              "const": "voiceStartPos",
              "description": "起播时间位置。"
            },
            "value": {
              "type": "integer",
              "minimum": 0,
              "description": "起播位置，单位为秒。例如第 10 分钟传 600，3 分 09 秒传 189。"
            }
          },
          "required": [
            "field",
            "value"
          ],
          "additionalProperties": false
        }
      ]
    }
  }
}

column9:
{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "智能体（影视、少儿）": {
            "type": "object",
            "properties": {
                "code": {
                    "type": "string",
                    "description": "接口返回状态码"
                },
                "data": {
                    "type": "object",
                    "properties": {
                        "ttscontent": {
                            "type": "string",
                            "description": "提示语\n对于影视智能体解析到问答意图的场景，统一返回默认值\"这个问题太深奥了，小聚还在学习呢\"\n\n对于少儿智能体解析到问答意图的场景，统一返回默认值\"这个问题太深奥了，小聚还在学习呢\""
                        },
                        "llmSemantic": {
                            "type": "object",
                            "properties": {
                                "query": {
                                    "type": "string"
                                },
                                "vectorQuery": {
                                    "type": "string",
                                    "description": "【新增】向量检索Query"
                                },
                                "domain": {
                                    "type": "string",
                                    "description": "固定值\n影视=影视领域（VIDEO_TOPIC）\n少儿=少儿领域（EDUC_TOPIC）"
                                },
                                "intent": {
                                    "type": "string",
                                    "description": "意图信息，按业务划分\n陪伴机器人新增vod_companion_robot_unsupported不支持意图"
                                },
                                "isNewVersion": {
                                    "type": "boolean",
                                    "description": "【新增】用于区分是否新版本，不传参默认false \n\n少儿智能体不需要传此值"
                                },
                                "content": {
                                    "type": "string",
                                    "description": "\"content\": \"{\\\"queryRetrievalIntent\\\":\\\"Multi_retrieval_intent\\\"}\"影视模糊意图下二次请求需要的必要参数，需终端二次流式请求时透传。 影视2.1新增wordList"
                                },
                                "largeModelSlotData": {
                                    "type": "object",
                                    "properties": {

                                    },
                                    "description": "大模型提槽信息(除模糊检索、个性化模糊检索和知识问答意图外其他意图可不传该值)"
                                },
                                "originalQuery": {
                                    "type": "string",
                                    "description": "原始query (除模糊检索、个性化模糊检索和知识问答意图外其他意图可不传该值)"
                                },
                                "rewriteQuery": {
                                    "type": "string",
                                    "description": "模型改写后的query (除模糊检索、个性化模糊检索和知识问答意图外其他意图可不传该值)"
                                }
                            },
                            "description": "意图信息",
                            "required": [
                                "domain",
                                "intent"
                            ]
                        },
                        "data": {
                            "type": "object",
                            "properties": {

                            },
                            "description": "媒资信息：按业务区分示例：\n影视=http://10.18.229.83:3000/project/1723/interface/api/185520\n少儿=http://10.18.229.83:3000/project/1723/interface/api/187527"
                        },
                        "ttsPolishParam": {
                            "type": "object",
                            "properties": {

                            },
                            "description": "精确搜索tts润色参数，精确搜索时必传，详见：http://10.18.229.83:3000/project/1753/interface/api/185418\n\n少儿精确搜索tts润色\nhttp://10.18.229.83:3000/project/1753/interface/api/188767"
                        },
                        "iotinfocheck": {
                            "type": "string",
                            "description": "(不确定含义，暂时保留)\n用于下发给终端标识，终端检测聚好看的推荐接口"
                        },
                        "multispeech": {
                            "type": "string",
                            "description": "（保留）多轮语音参数"
                        },
                        "ttsReplace": {
                            "type": "string",
                            "description": "（保留）\n是否需要RTG替换"
                        },
                        "sort": {
                            "type": "string",
                            "description": "（保留）\n分类，相同的UI下发sort相同\n对于影视智能体解析到问答意图的场景，统一返回默认值\"chatting\"\n"
                        },
                        "priority": {
                            "type": "string",
                            "description": "（保留）\n用于终端，是否优先级处理界面词"
                        },
                        "subsort": {
                            "type": "string",
                            "description": "（保留）子分类\n对于影视智能体解析到问答意图的场景，统一返回默认值\"chatting\"\n\n对于少儿 智能体解析到问答意图的场景，统一返回默认值\"chatting\""
                        },
                        "screenoper": {
                            "type": "string",
                            "description": "（保留）开关屏的参数，1：终端执行开屏，0：终端执行关屏，3：终端需要特殊逻辑处理"
                        },
                        "logId": {
                            "type": "string",
                            "description": "(确认含义，是否保留)请求参数中的logId。若logId为空，内部自动生成"
                        },
                        "fullduplex": {
                            "type": "string",
                            "description": "全双工参数，1：终端执行全双工交互，默认是0"
                        },
                        "extradata": {
                            "type": "object",
                            "properties": {
                                "video": {
                                    "type": "object",
                                    "properties": {
                                        "videorecommand": {
                                            "type": "array",
                                            "items": {
                                                "type": "object",
                                                "properties": {
                                                    "videonum": {
                                                        "type": "number",
                                                        "description": "资源编号"
                                                    },
                                                    "isrecommand": {
                                                        "type": "boolean",
                                                        "description": "资源编号"
                                                    }
                                                },
                                                "required": [
                                                    "videonum",
                                                    "isrecommand"
                                                ]
                                            }
                                        }
                                    },
                                    "description": "视频服务结果"
                                }
                            },
                            "description": "用于存放与业务无关参数；-----魔方屏增加"
                        },
                        "debugLog": {
                            "type": "object",
                            "properties": {

                            },
                            "description": "debug调试日志，不返回给终端；map结构，根据业务自行组装"
                        },
                        "memoryData": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "sort": {
                                        "type": "string",
                                        "description": "数据类别 少儿、影视固定为 hisapp"
                                    },
                                    "subsort": {
                                        "type": "string",
                                        "description": "数据子类 少儿、影视固定为 video"
                                    },
                                    "recognitionType": {
                                        "type": "string",
                                        "description": "识别类型，小聚识图用，其他来源传空字符串"
                                    },
                                    "text": {
                                        "type": "string",
                                        "description": "业务数据播报tts"
                                    },
                                    "serviceId": {
                                        "type": "string",
                                        "description": "服务Id 少儿固定值为 CHILD_AGENT_SERVICE\n影视固定值为 VIDEO_AGENT_SERVICE"
                                    },
                                    "data": {
                                        "type": "array",
                                        "items": {
                                            "type": "object",
                                            "properties": {
                                                "actor": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "string",
                                                        "description": ""
                                                    },
                                                    "description": "演员"
                                                },
                                                "childCategory": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "string",
                                                        "description": ""
                                                    },
                                                    "description": "子类"
                                                },
                                                "mediaTitle": {
                                                    "type": "string",
                                                    "description": "媒资名称"
                                                },
                                                "doubanRate": {
                                                    "type": "number",
                                                    "description": "豆瓣评分"
                                                },
                                                "director": {
                                                    "type": "array",
                                                    "items": {
                                                        "type": "string"
                                                    },
                                                    "description": "导演"
                                                },
                                                "guest": {
                                                    "type": "string"
                                                },
                                                "isClip": {
                                                    "type": "boolean",
                                                    "description": "是否片花"
                                                },
                                                "mediaId": {
                                                    "type": "integer",
                                                    "description": "format: int32",
                                                    "format": "int32"
                                                },
                                                "category": {
                                                    "type": "string",
                                                    "description": "种类 取categoryNameMark"
                                                },
                                                "pubdate": {
                                                    "type": "string",
                                                    "description": "发布日期"
                                                }
                                            },
                                            "required": [
                                                "actor",
                                                "childCategory",
                                                "mediaTitle",
                                                "doubanRate",
                                                "director",
                                                "category",
                                                "mediaId",
                                                "isClip",
                                                "guest",
                                                "pubdate"
                                            ]
                                        }
                                    }
                                },
                                "required": [
                                    "sort",
                                    "data",
                                    "serviceId",
                                    "text",
                                    "recognitionType",
                                    "subsort"
                                ]
                            },
                            "description": "记忆存储字段 影视不返回"
                        },
                        "memoryContent": {
                            "type": "string",
                            "description": "记忆信息存储，JSON格式字符串，其中memoryQuery存储本轮query：\n示例结构：\"memoryContent\": \"{\\\"memoryQuery\\\":\\\"query=(release_year:[20250522 TO 20260522])AND((category:\\\\\\\"电影\\\\\\\"))&sort=play,play desc,desc&appTypeSelected=1\\\"}\",\n"
                        }
                    },
                    "description": "返回数据",
                    "required": [
                        "llmSemantic",
                        "memoryData"
                    ]
                },
                "message": {
                    "type": "string",
                    "description": "接口返回状态描述"
                }
            },
            "description": "影视：bizType=vod\n少儿：bizType=educ"
        }
    },
    "required": [
        "code",
        "message",
        "data"
    ]
}

column8:
{
  "name": "vod_fuzzy_search",
  "title": "影视_媒资搜索_模糊搜索",
  "url": "https://api.example.com/vod/search",
  "method": "POST",
  "description": "影视媒资模糊搜索工具。用于处理用户以模糊、描述性等方式表达影视查找意图的场景，包括剧情描述、台词描述、复杂组合条件等，系统将自然语言解析为结构化筛选参数后进行检索。\n适用场景：1. 剧情/画面描述类查询，如\"骑着蓝色大鸟的人的电影\"、\"主角在沙漠里找水的片子\"；2. 复杂组合描述，如\"那个演功夫片的胖子导演的高分电影\"、\"不是国产的、评分高的、最近几年的科幻片\"；3. 台词/对白相关的模糊查找。",
  "parameters": {
    "type": "object",
    "description": "模糊搜索请求参数。由服务内部完成语义理解、槽位抽取和检索条件生成。",
    "properties": {
      "query": {
        "type": "string",
        "minLength": 1,
        "pattern": ".*\\S.*",
        "description": "模糊搜索子系统用户输入。"
      }
    },
    "required": [
      "query"
    ],
    "additionalProperties": false
  },
  "output": {
    "type": "object",
    "description": "影视模糊搜索/切片检索响应结果",
    "properties": {
      "messageType": {
        "type": "string",
        "enum": ["VIDEO"],
        "description": "消息类型，模糊搜索和切片检索固定为VIDEO"
      },
      "intention": {
        "type": "string",
        "enum": [
          "vod_vague_search",
          "vod_clip_plot_aggregate_search",
          "vod_clip_plot_search",
          "vod_clip_lines_search",
          "vod_clip_source_search"
        ],
        "description": "业务意图：vod_vague_search表示影视模糊搜索;vod_clip_plot_aggregate_search表示剧情聚合检索;vod_clip_plot_search表示剧情精确检索;vod_clip_lines_search表示台词精确检索;vod_clip_source_search表示剧情台词溯源检索"
      },
      "seq": {
        "type": "integer",
        "description": "返回数据包的序列号，从0开始递增"
      },
      "finish": {
        "type": "string",
        "enum": ["1", "0", "-1"],
        "description": "响应状态：1表示正常结束；0表示尚未结束（媒资超过6条时分包）；-1表示后端服务异常"
      },
      "mediaData": {
        "type": "object",
        "description": "媒资响应数据",
        "properties": {
          "ttscontent": {
            "type": "string",
            "description": "用于语音播报的提示语"
          },
          "data": {
            "type": "object",
            "description": "核心媒资信息，对应影视媒资信息响应接口(185520)的data结构",
            "properties": {
              "total": {
                "type": "integer",
                "description": "媒资总数"
              },
              "titledata": {
                "type": "string",
                "description": "展示标题/回复文案"
              },
              "viewtype": {
                "type": "string",
                "description": "展示类别，如searchviewnew"
              },
              "loginfo": {
                "type": "object",
                "description": "日志埋点信息，包含agenttype、agentintent等",
                "properties": {}
              },
              "content": {
                "type": "object",
                "description": "媒资内容",
                "properties": {
                  "isRecommend": {
                    "type": "boolean",
                    "description": "是否推荐"
                  },
                  "isAllShortMedia": {
                    "type": "boolean",
                    "description": "是否全部短视频"
                  },
                  "searchseq": {
                    "type": "string",
                    "description": "搜索序列号"
                  },
                  "searchurl": {
                    "type": "string",
                    "description": "搜索url"
                  },
                  "searchindex": {
                    "type": "integer",
                    "description": "搜索索引"
                  },
                  "dataSource": {
                    "type": "string",
                    "description": "搜索来源，如AI推荐、普通搜索、兜底搜索"
                  },
                  "luiInfo": {
                    "type": "string",
                    "description": "大模型LUI播报语，JSON字符串"
                  },
                  "searchResultList": {
                    "type": "array",
                    "description": "搜索结果列表",
                    "items": {
                      "type": "object",
                      "properties": {
                        "total": {
                          "type": "integer",
                          "description": "当前tab媒资总数"
                        },
                        "tipsfromjhk": {
                          "type": "array",
                          "description": "聚好看引导语"
                        },
                        "data": {
                          "type": "array",
                          "description": "媒资详情列表",
                          "items": {
                            "type": "object"
                          }
                        },
                        "appType": {
                          "type": "integer",
                          "description": "应用类型"
                        },
                        "appName": {
                          "type": "string",
                          "description": "应用名称"
                        }
                      }
                    }
                  }
                }
              }
            }
          },
          "iotinfocheck": {
            "type": "string",
            "description": "下发给终端的资源标识，终端可据此请求推荐接口"
          },
          "multispeech": {
            "type": "string",
            "description": "多轮语音参数"
          },
          "ttsReplace": {
            "type": "string",
            "description": "是否需要进行RTG替换"
          },
          "dataconfidence": {
            "type": "string",
            "description": "数据置信度"
          },
          "sort": {
            "type": "string",
            "description": "媒资分类，相同用户界面下发相同的sort值"
          },
          "priority": {
            "type": "string",
            "description": "终端处理优先级"
          },
          "subsort": {
            "type": "string",
            "description": "媒资子分类"
          },
          "screenoper": {
            "type": "string",
            "enum": ["0", "1", "3"],
            "description": "终端屏幕控制参数：1开屏；0关屏；3特殊逻辑处理"
          },
          "extradata": {
            "type": "object",
            "description": "与具体业务无关的扩展参数",
            "properties": {}
          },
          "logId": {
            "type": "string",
            "description": "请求日志标识"
          },
          "fullduplex": {
            "type": "string",
            "enum": ["0", "1"],
            "description": "全双工参数：1启用；0不启用（默认）"
          },
          "llmSemantic": {
            "type": "object",
            "description": "大模型识别出的业务意图信息",
            "properties": {
              "domain": {
                "type": "string",
                "description": "领域，如VIDEO_TOPIC"
              },
              "intent": {
                "type": "string",
                "description": "意图，如vod_vague_search"
              }
            }
          },
          "ttsPolishParam": {
            "type": "object",
            "description": "语音播报文本润色参数",
            "properties": {}
          },
          "memoryContent": {
            "type": "string",
            "description": "记忆信息，JSON格式字符串；其中memoryQuery字段保存本轮查询条件"
          },
          "vagueTtsContent": {
            "type": "string",
            "description": "模糊搜索回复语。第一包有值，第二包（若有）为空字符串"
          },
          "debugLog": {
            "type": "object",
            "description": "调试日志信息",
            "properties": {}
          }
        }
      },
      "memoryData": {
        "type": "array",
        "description": "记忆存储数据，仅第一包携带",
        "items": {
          "type": "object",
          "properties": {
            "sort": {
              "type": "string",
              "description": "数据类别，固定为hisapp"
            },
            "subsort": {
              "type": "string",
              "description": "数据子类，固定为video"
            },
            "recognitionType": {
              "type": "string",
              "description": "识别类型"
            },
            "text": {
              "type": "string",
              "description": "业务数据播报tts"
            },
            "serviceId": {
              "type": "string",
              "description": "服务Id，固定为VIDEO_AGENT_SERVICE"
            },
            "data": {
              "type": "array",
              "description": "媒资摘要列表",
              "items": {
                "type": "object",
                "properties": {
                  "mediaTitle": { "type": "string" },
                  "mediaId": { "type": "integer" },
                  "actor": { "type": "array", "items": { "type": "string" } },
                  "director": { "type": "array", "items": { "type": "string" } },
                  "childCategory": { "type": "array", "items": { "type": "string" } },
                  "category": { "type": "string" },
                  "doubanRate": { "type": "number" },
                  "pubdate": { "type": "string" },
                  "isClip": { "type": "boolean" }
                }
              }
            }
          }
        }
      }
    },
    "required": ["messageType", "intention", "seq", "finish"],
    "usage_hint": "模糊搜索/切片检索始终返回VIDEO类型。finish=0时为分包第一帧（含前6条媒资+vagueTtsContent+memoryData），需继续接收后续数据；finish=1时为最终帧（若为分包则含剩余媒资且vagueTtsContent为空）。媒资总数≤6条时只有一帧且finish=1。finish=-1表示后端服务异常。"
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "vod_relate_search",
  "description": "影视媒资相关检索工具(vod_relate_search)。当用户基于某个影视标题、演员、导演或分类请求相似、相关内容时触发，例如“类似流浪地球的电影”“推荐一些刘德华主演的相关影片”。支持4个精确匹配维度(title、actor、director、category)。同一维度包含多个值时，使用values数组传递，并通过operator指定逻辑关系：or表示任一值匹配，and表示所有值均需匹配，默认为or。不同维度之间通过BoolNode使用and(与)、or(或)、not(非)组合，支持任意嵌套。本工具仅用于相关推荐，不负责内容起播。",
  "type": "object",
  "properties": {
    "query": {
      "$ref": "#/definitions/QueryNode",
      "description": "相关推荐条件的根节点。可以是单个字段条件，也可以是由AND、OR、NOT组成的复合条件。"
    }
  },
  "required": [
    "query"
  ],
  "additionalProperties": false,
  "definitions": {
    "QueryNode": {
      "description": "相关推荐查询节点，可以是布尔组合节点或单个字段条件节点。",
      "oneOf": [
        {
          "$ref": "#/definitions/BoolNode"
        },
        {
          "$ref": "#/definitions/FieldCondition"
        }
      ]
    },
    "BoolNode": {
      "description": "布尔逻辑组合节点，支持AND、OR、NOT，并允许递归嵌套。",
      "type": "object",
      "oneOf": [
        {
          "properties": {
            "and": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/QueryNode"
              },
              "minItems": 1,
              "description": "AND逻辑：所有子节点条件必须同时满足。"
            }
          },
          "required": [
            "and"
          ],
          "additionalProperties": false
        },
        {
          "properties": {
            "or": {
              "type": "array",
              "items": {
                "$ref": "#/definitions/QueryNode"
              },
              "minItems": 1,
              "description": "OR逻辑：至少满足一个子节点条件。"
            }
          },
          "required": [
            "or"
          ],
          "additionalProperties": false
        },
        {
          "properties": {
            "not": {
              "$ref": "#/definitions/QueryNode",
              "description": "NOT逻辑：排除满足该子节点条件的内容。"
            }
          },
          "required": [
            "not"
          ],
          "additionalProperties": false
        }
      ]
    },
    "FieldCondition": {
      "description": "相关推荐字段条件。支持title、actor、director、category四个维度，可使用value传递单值，或使用values传递多个值。",
      "type": "object",
      "properties": {
        "field": {
          "type": "string",
          "description": "相关推荐条件的字段名称。",
          "oneOf": [
            {
              "const": "title",
              "description": "参考媒资标题，例如流浪地球、甄嬛传。通常用于查找与指定媒资相似或相关的内容。"
            },
            {
              "const": "actor",
              "description": "演员名称，例如刘德华、周星驰。用于推荐相关演员参演的内容。"
            },
            {
              "const": "director",
              "description": "导演名称，例如张艺谋、冯小刚。用于推荐相关导演执导的内容。"
            },
            {
              "const": "category",
              "description": "影视分类，例如电影、电视剧、纪录片、综艺、戏曲、新闻、资讯、片花、短视频、广告、正片、动漫。用于限制推荐内容的分类。"
            }
          ]
        },
        "value": {
          "type": "string",
          "minLength": 1,
          "description": "单值匹配条件。使用value时不得同时传递values或operator。"
        },
        "values": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "minItems": 1,
          "uniqueItems": true,
          "description": "多值匹配条件。数组中的值不得为空或重复，多个值之间的关系由operator决定。"
        },
        "operator": {
          "type": "string",
          "enum": [
            "and",
            "or"
          ],
          "default": "or",
          "description": "同一字段包含多个值时的逻辑关系。or表示任一值匹配，and表示所有值均需匹配，默认为or；仅在使用values时生效。"
        }
      },
      "required": [
        "field"
      ],
      "oneOf": [
        {
          "required": [
            "value"
          ],
          "not": {
            "anyOf": [
              {
                "required": [
                  "values"
                ]
              },
              {
                "required": [
                  "operator"
                ]
              }
            ]
          }
        },
        {
          "required": [
            "values"
          ],
          "not": {
            "required": [
              "value"
            ]
          }
        }
      ],
      "additionalProperties": false
    }
  }
}

{
  "name": "vod_personalized_search",
  "title": "影视个性化媒资检索",
  "method": "POST",
  "description": "功能：基于用户历史偏好进行个性化影视内容推荐，根据用户的观看记录、兴趣标签等画像信息推荐用户可能感兴趣的媒资内容。\n适用场景：用户表达了个性化推荐意图时使用，如\"推荐我喜欢的电影\"、\"给我推荐点好看的\"、\"推荐我喜欢的视频\"、\"有什么好看的推荐一下\"。可带分类参数如\"推荐我喜欢的综艺\"，也可不带分类如\"推荐我喜欢的视频\"。\n不适用场景：1. 用户指定了具体参考媒资要求相似推荐时不要调用，如\"推荐类似琅琊榜的\"，应使用vod_relate_search；2. 用户以模糊描述查找影视时不要调用，如\"骑着蓝色大鸟的人的电影\"，应使用vod_slow_search；3. 用户直接指定影视名称要求播放时不要调用，如\"播放琅琊榜\"。\n关联工具：相似媒资推荐用vod_relate_search，复杂语义搜索用vod_slow_search，明确查询用vod_search。\n异常：用户无历史偏好数据时返回error_code=NO_USER_PREFERENCE；参数格式错误时返回error_code=INVALID_PARAMETER。\n结果使用：根据解析出的分类偏好从用户画像中匹配推荐内容；当未传category时基于用户整体兴趣进行推荐。",
  "parameters": {
    "type": "object",
    "properties": {
      "category": {
        "type": "string",
        "description": "影视分类（可选）。指定推荐的分类范围，不传时基于用户整体兴趣推荐。",
        "enum": ["电影","电视剧","纪录片","综艺","戏曲","新闻","资讯","片花","短视频","广告","正片","动漫"]
      }
    },
    "required": []
  },
  "output": {
    "type": "object",
    "properties": {
      "category": {
        "type": "string",
        "description": "分类偏好解析结果，单个值，未传时为空"
      }
    },
    "usage_hint": "category为用户指定的推荐分类范围；未传时基于用户整体兴趣画像进行跨分类推荐"
  },
  "error_output": {
    "type": "object",
    "properties": {
      "error_code": {"type": "string", "description": "错误码，NO_USER_PREFERENCE=用户无历史偏好数据，INVALID_PARAMETER=参数格式错误"},
      "error_message": {"type": "string", "description": "错误描述信息"}
    }
  },
  "examples": [
    {
      "scenario": "推荐我喜欢的电影",
      "input": {
        "category": "电影"
      },
      "output": {
        "category": "电影"
      }
    },
    {
      "scenario": "推荐我喜欢的综艺",
      "input": {
        "category": "综艺"
      },
      "output": {
        "category": "综艺"
      }
    },
    {
      "scenario": "推荐我喜欢的视频（不带分类限定）",
      "input": {},
      "output": {}
    },
    {
      "scenario": "有什么好看的推荐一下",
      "input": {},
      "output": {}
    },
    {
      "scenario": "用户无历史偏好数据",
      "input": {
        "category": "电影"
      },
      "output": {
        "error_code": "NO_USER_PREFERENCE",
        "error_message": "暂无用户偏好数据，无法进行个性化推荐"
      }
    }
  ]
}

{
  "name": "vod_history",
  "title": "影视历史记录查询",
  "url": "[https://api.example.com/vod/history/query](https://api.example.com/vod/history/query)",
  "method": "POST",
  "description": "功能：查询用户的历史观看记录，支持按影视分类和精确时间范围筛选，返回符合条件的历史记录。\n适用场景：用户表达了查看历史记录的意图时使用，如“我看过的电影”、“最近看了什么”、“上个月看过的综艺”、“我的观看历史”、“查一下我的播放记录”。\n不适用场景：1. 用户非历史记录媒资查询时不要调用；2. 用户要求推荐内容时不要调用，应使用vod_personalized_recommendation或vod_media_recommendation；3. 用户要求播放某个具体影视时不要调用。\n关联工具：个性化推荐用vod_personalized_recommendation，相似推荐用vod_media_recommendation。\n时间解析：time 按 Asia/Shanghai（北京时间）解析，格式为“yyyy-MM-dd HH:mm:ss TO yyyy-MM-dd HH:mm:ss”，起止时间均包含。月：支持本月、上个月、上上个月，范围为对应月份第一天00:00:00至最后一天23:59:59。周：一周从周一开始，支持本周、这周、上周、上上周，以及本周一至本周日、上周一至上周日，范围为对应日期或周的起止时间。日：支持今天、昨天、前天、大前天、本月第一天、本月最后一天、上个月第一天、上个月最后一天。未指定时段时，日期范围为当天00:00:00至23:59:59。时段：凌晨为01:00:00至04:59:59；早、早上、清晨为05:00:00至07:59:59；上午为08:00:00至10:59:59；中、中午、正午为11:00:00至12:59:59；下午为13:00:00至16:59:59；傍晚、黄昏为17:00:00至18:59:59；晚上为19:00:00至22:59:59；深夜、子夜为当日23:00:00至次日00:59:59。只出现时段词但未指定日期时，按当天解析。\n限制：仅支持单日或单个连续时间范围；不支持“上周晚上”“本月早上”等跨多天且包含多个不连续时段的条件。\n异常：用户无历史记录时返回error_code=NO_HISTORY_RECORD；参数格式错误或不支持的不连续时间条件时返回error_code=INVALID_PARAMETER。\n结果使用：category为系统解析的分类筛选条件，time为解析出的单个连续精确时间范围；未传字段表示不做该维度限制。",
  "parameters": {
    "type": "object",
    "properties": {
      "category": {
        "type": "string",
        "description": "影视分类。指定查询的历史记录分类范围，不传时查询所有分类的历史记录。",
        "enum": ["电影","电视剧","纪录片","综艺","戏曲","新闻","资讯","片花","短视频","广告","正片","动漫""]
      },
      "time": {
        "type": "string",
        "description": "精确时间范围。格式为“yyyy-MM-dd HH:mm:ss TO yyyy-MM-dd HH:mm:ss”，例如“2026-07-12 18:00:00 TO 2026-07-12 23:59:59”。按北京时间解析，起止时间均包含；不传时查询全部历史记录。仅支持单个连续时间范围。",
        "pattern": "^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2} TO \\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$"
      }
    },
    "required": []
  },
  "output": {
    "type": "object",
    "properties": {
      "category": {
        "type": "string",
        "description": "分类筛选解析结果，单个值，未传时为空。"
      },
      "time": {
        "type": "string",
        "description": "精确时间范围解析结果，格式为“yyyy-MM-dd HH:mm:ss TO yyyy-MM-dd HH:mm:ss”，未传时为空。"
      }
    },
    "usage_hint": "category和time为系统从用户自然语言中解析出的查询条件，用于筛选历史观看记录；未传字段表示不做该维度限制。"
  },
  "error_output": {
    "type": "object",
    "properties": {
      "error_code": {
        "type": "string",
        "description": "错误码，NO_HISTORY_RECORD=用户无历史记录，INVALID_PARAMETER=参数格式错误或不支持的不连续时间范围。"
      },
      "error_message": {
        "type": "string",
        "description": "错误描述信息。"
      }
    }
  },
  "examples": [
    {
      "scenario": "我看过的电影",
      "input": {
        "category": "电影"
      },
      "output": {
        "category": "电影"
      }
    },
    {
      "scenario": "上个月看过的综艺（假设当前日期为2026-07-13）",
      "input": {
        "category": "综艺",
        "time": "2026-06-01 00:00:00 TO 2026-06-30 23:59:59"
      },
      "output": {
        "category": "综艺",
        "time": "2026-06-01 00:00:00 TO 2026-06-30 23:59:59"
      }
    },
    {
      "scenario": "昨天晚上的纪录片（假设当前日期为2026-07-13）",
      "input": {
        "category": "纪录片",
        "time": "2026-07-12 19:00:00 TO 2026-07-12 22:59:59"
      },
      "output": {
        "category": "纪录片",
        "time": "2026-07-12 19:00:00 TO 2026-07-12 22:59:59"
      }
    },
    {
      "scenario": "上周三傍晚看过什么（假设当前日期为2026-07-13）",
      "input": {
        "time": "2026-07-08 17:00:00 TO 2026-07-08 18:59:59"
      },
      "output": {
        "time": "2026-07-08 17:00:00 TO 2026-07-08 18:59:59"
      }
    },
    {
      "scenario": "最近看了什么（不带任何筛选）",
      "input": {},
      "output": {}
    },
    {
      "scenario": "用户无历史记录",
      "input": {},
      "output": {
        "error_code": "NO_HISTORY_RECORD",
        "error_message": "暂无历史观看记录"
      }
    }
  ]
}

