{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "data(历史记录 930)": {
            "type": "object",
            "properties": {
                "loginfo": {
                    "type": "object",
                    "properties": {
                        "appname": {
                            "type": "string",
                            "description": "同现有的搜索结果data下的appname"
                        },
                        "isStatistics": {
                            "type": "string",
                            "description": "是否上报聚好看"
                        },
                        "pagetype": {
                            "type": "number",
                            "description": "页面类别：0：表示直达媒资详情页；1：表示直达页面"
                        },
                        "query": {
                            "type": "string",
                            "description": "搜索串或直达词"
                        },
                        "url": {
                            "type": "string",
                            "description": "搜索接口地址"
                        },
                        "viewtype": {
                            "type": "string",
                            "description": "现有逻辑的viewtype"
                        },
