            "description": "历史记录"
        }
    },
    "required": [
        "data(历史记录 930)"
    ]
}

column8:
{
  "name": "vod_clip_search",
  "title": "影视_媒资切片搜索",
  "url": "https://api.example.com/vod/search",
  "method": "POST",
  "description": "功能：影视媒资剧情及台词切片搜索。用于处理用户以模糊、描述性、问答等方式表达影视片段查找意图的场景，包括剧情片段描述、台词描述、名场面集锦、片段溯源等，系统将自然语言解析为结构化筛选参数后进行检索。通过intent参数区分四种检索意图：剧情聚合检索（名场面/集锦汇总）、剧情检索（具体剧情片段）、台词检索（具体台词片段）、剧情台词溯源检索（查找台词或剧情出处）。",
  "parameters": {
    "type": "object",
    "properties": {
      "intent": {
        "type": "string",
        "description": "检索意图类型（必传）。plot_aggregate：剧情聚合检索；plot：具体剧情片段检索；lines：具体台词片段检索；source：剧情或台词出处溯源。",
        "enum": [
          "plot_aggregate",
          "plot",
          "lines",
          "source"
        ]
      },
      "query": {
        "type": "string",
        "description": "用户原始输入语料（必传），完整保留用户的自然语言表达，不做改写或截断。它承载剧情/画面描述、台词内容或片段溯源问题，是切片语义检索的核心依据；可与title、actor、tag等结构化筛选条件共同使用。如：\"安欣菜市场抓人片段\"、\"甄嬛传里臣妾做不到啊\"、\"华强买瓜出自哪部剧\"。"
      },
      "title": {
        "type": "string",
        "description": "媒资标题，如电影名、电视剧名、综艺名、动漫名、短视频标题等。"
      },
      "actor": {
        "type": "string",
        "description": "演员名。支持单值、NOT排除、AND同时包含、OR任一包含。例如：\"刘德华\"、\"NOT 刘德华\"、\"刘德华 AND 吴京\"、\"刘德华 OR 吴京\"。"
      },
      "age": {
        "type": "string",
        "description": "影视不使用该参数。年龄范围：\"6 TO 12\"、\"* TO 12\"、\"6 TO *\"。"
      },
      "category": {
        "type": "string",
        "description": "一级分类筛选，如\"电影\"、\"电视剧\"、\"综艺\"、\"动漫\"等。"
      },
      "date": {
        "type": "string",
        "description": "日期筛选或排序。支持：\"20200101 TO 20231231\"、\"* TO 20231231\"、\"20200101 TO *\"、\"latest-3-Y\"、\"latest-6-M\"、\"latest-30-D\"、\"desc\"、\"asc\"。"
      },
      "director": {
        "type": "string",
        "description": "导演名，支持单值、NOT、AND、OR四种模式。"
      },
      "entertainer": {
        "type": "string",
        "description": "参与人员，如配音、主持、嘉宾等；支持单值、NOT、AND、OR四种模式。"
      },
      "is_fee": {
        "type": "string",
        "description": "是否收费筛选。",
        "enum": [
          "0",
          "1"
        ]
      },
      "rate": {
        "type": "string",
        "description": "评分筛选与排序。支持：\"8 TO *\"、\"* TO 6\"、\"desc\"、\"asc\"。"
      },
      "tag": {
        "type": "string",
        "description": "标签筛选。支持：\"动作\"、\"NOT 恐怖\"、\"动作 AND 喜剧\"。"
      },
      "play": {
        "type": "string",
        "description": "播放量排序，支持\"desc\"或\"asc\"。"
      },
      "hot": {
        "type": "string",
        "description": "热度排序，支持\"desc\"或\"asc\"。"
      },
      "country": {
        "type": "string",
        "description": "影视所属国家或地区名，如\"中国\"、\"美国\"、\"韩国\"、\"日本\"等。"
      }
    },
    "required": [
      "intent",
      "query"
    ]
  },
  "output": {
    "type": "object",
    "properties": {
      "results": {
        "type": "object",
        "description": "搜索结果，包含解析后的筛选条件回显及检索意图。",
        "properties": {
          "intent": {
            "type": "string",
            "description": "实际生效的检索意图，回显传入的intent值。",
            "enum": [
              "plot_aggregate",
              "plot",
              "lines",
              "source"
            ]
          },
          "query": {
            "type": "string",
            "description": "实际参与切片语义检索的用户原始输入语料，回显传入的query值。"
          },
          "actor": {
            "type": "string",
            "description": "演员筛选条件。"
